import { formatEuros, roundCents } from './money.js';
import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }>, dueDate?: string, payments?: Array, voucher?: { code: string, amount: number } }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown';

  // Invoice header
  const number = invoice.number ?? 'DRAFT';
  const output = [number, customerName];

  // Line items with discounts
  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    let lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lineTotal)}`;

    // Show line discount if present (from discountPercent or bulk discount)
    const discountPercent = line.discountPercent ?? 0;
    const lineDiscount = roundCents(lineTotal * discountPercent / 100);
    let amountAfterDiscount = lineTotal - lineDiscount;
    let bulkDiscount = 0;

    if (line.qty >= 10 && amountAfterDiscount > 0) {
      bulkDiscount = roundCents(amountAfterDiscount * 2.5 / 100);
      amountAfterDiscount -= bulkDiscount;
    }

    const totalLineDiscount = lineDiscount + bulkDiscount;
    if (totalLineDiscount > 0) {
      lineText += ` (−${formatEuros(totalLineDiscount)})`;
    }

    output.push(lineText);
  }

  // Subtotal, discount, VAT, and total
  const totals = invoiceTotals(invoice);
  if (totals.vat > 0) {
    output.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Voucher if present
  if (invoice.voucher && invoice.voucher.amount > 0) {
    output.push(`Voucher ${invoice.voucher.code}: −${formatEuros(invoice.voucher.amount)}`);
  }

  output.push(`Total: ${formatEuros(totals.total)}`);

  // Due date if present
  if (invoice.dueDate) {
    output.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    output.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return output.join('\n');
}

