test('renderInvoiceText order: VAT, Voucher, Total, Due, Paid', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 3000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  issued.dueDate = '2024-02-14';

  const withPayment = recordPayment(issued, { amount: 2500, date: '2024-02-15' }).value;
  const text = renderInvoiceText(withPayment);
  const lines = text.split('\n');

  let vatIdx = -1, voucherIdx = -1, totalIdx = -1, dueIdx = -1, paidIdx = -1;

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].match(/^VAT:/)) vatIdx = i;
    if (lines[i].match(/^Voucher/)) voucherIdx = i;
    if (lines[i].match(/^Total:/)) totalIdx = i;
    if (lines[i].match(/^Due:/)) dueIdx = i;
    if (lines[i].match(/^Paid:/)) paidIdx = i;
  }

  assert.ok(vatIdx > -1, 'Should have VAT line');
  assert.ok(voucherIdx > vatIdx, 'Voucher should be after VAT');
  assert.ok(totalIdx > voucherIdx, 'Total should be after Voucher');
  assert.ok(dueIdx > totalIdx, 'Due should be after Total');
  assert.ok(paidIdx > dueIdx, 'Paid should be after Due');
});

