import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for unpublished invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows the invoice number when issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText shows the customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText formats line items with quantities and totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Lines with qty >= 10 have bulk discount displayed
  assert.match(lines[2], /^10 × Design work \(hour\) @ €85\.00 = €850\.00 \(−/);
  assert.match(lines[3], /^100 × Sticker sheet @ €0\.50 = €50\.00 \(−/);
});

test('renderInvoiceText formats amounts with thousands separators', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.match(text, /€2,400\.00/);
});

test('renderInvoiceText shows the total at the end', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 20 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lastLine = text.split('\n').pop();

  assert.match(lastLine, /^Total: €/);
});

test('renderInvoiceText calculates the correct total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 100 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];

  // DES-HOUR: 85000, tier 4250, after 80750, bulk 2018, after 82732, vat 17374
  // STICKER: 5000, tier 250, after 4750, bulk 118, after 4632, vat 973
  // Total: 90000 - 6636 + 18347 = 100869 cents = €1,008.69
  assert.equal(lastLine, 'Total: €1,008.69');
});

test('renderInvoiceText handles multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // number, customer, 3 product lines, VAT, total (no discounts for qty < 10)
  assert.equal(lines.length, 7);
  assert.match(lines[2], /Design work/);
  assert.match(lines[3], /Development/);
  assert.match(lines[4], /Copywriting/);
});

test('renderInvoiceText preserves line order', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'BRAND-BOOK', qty: 1 },
      { sku: 'ICON-SET', qty: 10 },
      { sku: 'STICKER', qty: 50 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[2], /Brand guidelines/);
  assert.match(lines[3], /Icon set/);
  assert.match(lines[4], /Sticker sheet/);
});

test('renderInvoiceText shows VAT line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /^VAT: €/m);
});

test('renderInvoiceText does not show VAT line when VAT is 0', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /^VAT:/m);
});

