    ],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SUMMER10', amount: 5000 }).value;
  const text = renderInvoiceText(withVoucher);
  const lines = text.split('\n');

  let foundVoucher = false;
  for (let i = 0; i < lines.length - 1; i++) {
    if (lines[i].match(/Voucher SUMMER10/)) {
      assert.match(lines[i + 1], /^Total:/);
      foundVoucher = true;
      break;
    }
  }
  assert.ok(foundVoucher, 'Voucher line should appear before Total');
});

